from typing import Optional, Union

from taf.nms.netact.nodes_factory import NodesFactory

from .fmcli_operations import CancelAlarms, ChangeMaintenanceMode, UploadAlarms
from .mixins import FmRestApiMixin, IntegrationDataMixin


class MonitorFm(FmRestApiMixin,
                IntegrationDataMixin,
                ):

    def __init__(self, nodes_factory: NodesFactory) -> None:
        self.nodes = nodes_factory

    def cancel_alarms(self,
                      dist_name: str,
                      alarm_number: Optional[Union[int, str]] = None,
                      alarm_file: Optional[str] = None,
                      include_subnetworks: Optional[bool] = False
                      ) -> str:
        """
        Use the bulkcancelalarms operation of the fmCLI.sh script to cancel alarms.
        http://belk.netact.noklab.net/N1X_TRUNK/topic/fm_command_line_operations/tasks/bulk_cancel_of_alarms.html

        :param string dist_name:
        :param string alarm_number: The maximum number of parallel alarm cancel operations supported is 10.
            When alarm cancel operations are initiated beyond the maximum number, the operation fails with a message.
        :param string alarm_file: If alarm_file is given absolute path of the alarm file must be provided
        :param bool include_subnetworks: Specifies if child managed objects of distinguished name must be considered
            while performing alarm cancel operation. The default value set is false
        :return: command output
        :rtype: string
        """
        fmwas_node = self.nodes.get_node('fmwas')
        return CancelAlarms(fmwas_node).execute(dist_name, alarm_number, alarm_file, include_subnetworks)

    def upload_alarms(self, dist_name):
        """
        Execute the alarmupload operation of the fmCLI.sh script to upload alarms.

        More in NA Operating Documentation at:
        Fault Management > Fault Management Operating Procedures
        > Fault Management Command Line Operations > Executing command line

        :param dist_name:
        :return: command output
        :rtype: string
        """
        fmwas_node = self.nodes.get_node('fmwas')
        return UploadAlarms(fmwas_node).execute(dist_name)

    def change_maintenance_mode(self, operation_type, dist_name, comment=None, include_subtree=False):
        """
        Execute the ``mamo`` operation of the fmCLI.sh script.

        More in NA Operating Documentation at:
        Fault Management > Fault Management Operating Procedures
        > Fault Management Command Line Operations > Executing command line

        :param string dist_name: e.g. 'PLMN-1/BSC-1'
        :param bool include_subtree: Specifies if subtree has to be included for maintenance mode operation
        :param string comment: Comment to be provided while setting distinguished name under maintenance mode
        :return: command output, e.g., 'Set under maintenance mode: SUCCESS'
        :rtype: string
        """
        fmwas_node = self.nodes.get_node('fmwas')
        return ChangeMaintenanceMode(fmwas_node).execute(operation_type,
                                                         dist_name,
                                                         comment,
                                                         include_subtree)
